import { createHash, randomBytes, randomInt } from 'node:crypto';
import { ROOM_CODE_ALPHABET } from '@moises/shared';

// Identifiers generated by the server from the OS CSPRNG. Clients never
// choose an id, a token or a room code.

/** 12 base64url characters (72 bits). Public: other players see it. */
export function newPlayerId(): string {
  return randomBytes(9).toString('base64url');
}

/** 43 base64url characters (256 bits). Secret: only its owner receives it. */
export function newSessionToken(): string {
  return randomBytes(32).toString('base64url');
}

/** Tokens are stored only as SHA-256 hashes, so a memory dump or log line never holds a usable token. */
export function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('base64url');
}

/**
 * Random room code. With the default 6 characters there are 31^6 (about 887
 * million) codes; together with the per-connection rate limit that is enough
 * for a casual game (codes are short-lived and rooms are few).
 */
export function newRoomCode(length: number, pick: (max: number) => number = randomInt): string {
  let code = '';
  for (let i = 0; i < length; i++) code += ROOM_CODE_ALPHABET[pick(ROOM_CODE_ALPHABET.length)];
  return code;
}
